<template>
  <div class="app-container">
    <div class="page-hero"><div class="hero-inner"><div class="hero-text"><h1 class="hero-title">Kaplan-Meier 生存分析</h1><p class="hero-desc">乘积极限法估计生存函数，适用于含删失数据的生存分析。输入生存时间和结局（1=事件/0=删失），输出生存曲线、生存表和中位生存时间</p></div><el-tag class="hero-tag" effect="dark" round>SURVIVAL · KAPLAN-MEIER</el-tag></div></div>
    <el-row :gutter="20" class="mb-4 input-row">
      <el-col :lg="16" :xs="24"><el-card shadow="never" class="input-card"><el-form label-position="top"><el-form-item label="数据（每行：生存时间,结局 1=事件 0=删失）"><el-input v-model="form.rawData" type="textarea" :rows="6" /></el-form-item></el-form><div class="action-bar"><el-button type="primary" class="calc-btn" @click="calculate"><el-icon class="mr-1"><DataAnalysis /></el-icon>开始计算</el-button><el-button class="reset-btn" @click="loadDemo">加载示例</el-button><el-button class="reset-btn" @click="clearAll">清除</el-button></div></el-card></el-col>
      <el-col :lg="8" :xs="24"><div class="param-sidebar"><div class="param-sidebar-header"><el-icon class="sidebar-icon"><InfoFilled /></el-icon>检验原理</div><div class="principle-content"><div class="principle-block"><div class="principle-label">方法</div><p>乘积极限法（Product-Limit）</p><div class="formula-box">Ŝ(t) = Π(1 - dᵢ/nᵢ)</div></div><div class="principle-block"><div class="principle-label">删失处理</div><p>删失个体不计入事件数，但参与风险集计算</p></div></div><div class="ref-section"><div class="ref-title">参考文献</div><p class="ref-item">[1] 方积乾.《卫生统计学》第7版, 2012.</p><p class="ref-item">[2] Kaplan EL, Meier P. JASA, 1958.</p></div></div></el-col>
    </el-row>
    <transition name="result-fade"><div v-if="res" class="result-section">
      <div class="metrics-grid mb-5"><div v-for="m in metrics" :key="m.label" class="metric-card" :class="m.type"><div class="metric-indicator" /><div class="metric-label">{{ m.label }}</div><div class="metric-value">{{ m.value }}</div></div></div>
      <el-row :gutter="20" class="mb-4">
        <el-col :lg="12" :xs="24" class="mb-4"><el-card shadow="never" class="detail-card"><template #header><div class="card-header-inner"><el-icon class="header-icon"><TrendCharts /></el-icon><span class="font-bold">生存曲线</span></div></template><ECharts :options="chartOpts" height="340px" /></el-card></el-col>
        <el-col :lg="12" :xs="24" class="mb-4"><el-card shadow="never" class="detail-card"><template #header><div class="card-header-inner"><el-icon class="header-icon"><Document /></el-icon><span class="font-bold">生存表</span></div></template><el-table :data="tableRows" size="small" stripe border max-height="340"><el-table-column prop="time" label="时间" width="70" /><el-table-column prop="nRisk" label="风险集" width="70" /><el-table-column prop="events" label="事件" width="60" /><el-table-column prop="censored" label="删失" width="60" /><el-table-column prop="survival" label="S(t)" width="90" /></el-table></el-card></el-col>
      </el-row>
    </div></transition>
  </div>
</template>
<script setup lang="ts">
import { InfoFilled, DataAnalysis, TrendCharts, Document } from "@element-plus/icons-vue"; import * as S from "../utils/stats";
defineOptions({ name: "KaplanMeier" }); const form = reactive({ rawData: "" }); const res = ref(false); const metrics = ref<any[]>([]); const chartOpts = ref({}); const tableRows = ref<any[]>([]);
function loadDemo() { form.rawData = "1,1\n2,1\n3,0\n4,1\n5,1\n6,0\n7,1\n8,1\n10,0\n12,1\n15,0\n18,1\n20,0\n24,1\n30,0"; calculate(); }
function clearAll() { form.rawData = ""; res.value = false; }
function calculate() {
  const rows = form.rawData.trim().split("\n").map(l => { const p = S.parseNumbers(l); return { time: p[0], event: p[1] }; }).filter(r => r.time != null).sort((a, b) => a.time - b.time);
  const n = rows.length; let atRisk = n, survival = 1, totalEvents = 0, totalCensored = 0;
  const times = [...new Set(rows.map(r => r.time))].sort((a, b) => a - b);
  const table: any[] = []; const curve: [number, number][] = [[0, 1]];
  times.forEach(t => { const events = rows.filter(r => r.time === t && r.event === 1).length; const censored = rows.filter(r => r.time === t && r.event === 0).length; if (events > 0) survival *= (1 - events / atRisk); table.push({ time: t, nRisk: atRisk, events, censored, survival: S.fmt(survival) }); curve.push([t, +survival.toFixed(4)]); totalEvents += events; totalCensored += censored; atRisk -= events + censored; });
  let medianSurvival = "-"; for (const row of table) { if (+row.survival <= 0.5) { medianSurvival = String(row.time); break; } }
  res.value = true; tableRows.value = table;
  metrics.value = [{ label: "总例数", value: n, type: "accent" }, { label: "事件数", value: totalEvents, type: "warning" }, { label: "删失数", value: totalCensored, type: "success" }, { label: "中位生存时间", value: medianSurvival, type: "accent" }];
  chartOpts.value = { tooltip: { trigger: "axis" }, grid: { left: "8%", right: "4%", bottom: "10%", top: "6%" }, xAxis: { type: "value", name: "时间" }, yAxis: { type: "value", name: "S(t)", max: 1 }, series: [{ type: "line", data: curve, step: "end", lineStyle: { width: 2.5, color: "#4558d0" }, showSymbol: false, areaStyle: { opacity: 0.06 } }] };
}
</script>
